function aCrossView() { let group = {}; aRows().filter(r => r.window === aWindow && r.story_id).forEach(r => (group[r.story_id] ??= []).push(r)); let matched = Object.entries(group).filter(([_, rows]) => new Set(rows.map(r => r.platform)).size >= 2); let metric = 'comments'; return `<div class="a-header"><div class="row-spaced"><div><span class="micro">CROSS-PLATFORM STORY RESONANCE</span><h3 style="margin:6px 0 4px">Same story, different audience</h3><p class="a-panel-desc" style="margin:0">Match story IDs across channels. Compare each post’s performance relative to its own platform.</p></div>${aSampleFlag()}</div><div class="a-filterline"><div class="a-field tiny-field"><label>Age-matched snapshots</label><select onchange="aSetWindow(this.value)">${A_WINDOWS.map(w => `<option ${w === aWindow ? 'selected' : ''}>${w}</option>`).join('')}</select></div><div class="a-field"><label>Comparable indicator</label><select id="crossMetric" onchange="document.getElementById('crossTableWrap').innerHTML=aCrossTable(this.value)"><option value="comments">Comments</option><option value="profile_visits">Profile visits</option><option value="views">Native views (directional)</option></select></div></div></div><div class="a-banner" style="margin-top:18px"><span>⚑</span><div><strong>Relative-percentile method</strong> Each post is ranked among posts on its own platform using the same metric and age window. This is a directional creative signal, not a claim that raw Instagram, Facebook and LinkedIn metrics are interchangeable. Percentiles require at least five observations.</div></div><div class="a-panel"><div class="a-topline"><h3>Matched creative performance</h3><span class="tag">${matched.length} shared story IDs</span></div><div id="crossTableWrap">${aCrossTable(metric)}</div></div><div class="a-2col" style="margin-top:18px"><section class="a-panel"><h3>What to learn from cross-posting</h3><div class="a-insight" style="margin-top:19px"><span class="micro">Observation</span><p>Compare the same narrative on different platforms without conflating viewer origins or metric definitions.</p></div><div class="a-insight"><span class="micro">Interpretation</span><p>Differences may reflect delivery, format, follower mix, post timing, or audience—not simply the caption.</p></div><div class="a-insight"><span class="micro">Next test</span><p>Publish paired story angles on both platforms with a consistent objective and compare them at 7 days.</p></div></section><section class="a-panel"><h3>Important safeguards</h3>${[['Same post age', '48-hour posts compare with 48-hour posts, not mature 30-day posts.'], ['Within-platform percentiles', 'Avoid raw cross-platform “winners” without harmonised definitions.'], ['Same creative ID', 'Do not assume a story is identical if edited for different audiences.'], ['Separate audience source', 'Instagram and Facebook audience origins never merged.']].map(([t, b]) => `<div class="checkline"><span class="checkmark">✓</span><div><strong>${t}</strong><p>${b}</p></div></div>`).join('')}</section></div>` }
function aCrossTable(metric) { let group = {}; aRows().filter(r => r.window === aWindow && r.story_id).forEach(r => (group[r.story_id] ??= []).push(r)); let matched = Object.entries(group).filter(([_, rs]) => new Set(rs.map(r => r.platform)).size >= 2); return matched.length ? `<div class="a-table-wrap"><table class="a-table"><thead><tr><th>Story</th><th>Instagram</th><th>Facebook</th><th>LinkedIn</th><th>Directional finding</th></tr></thead><tbody>${matched.map(([story, rs]) => { let vals = A_PLATFORMS.map(p => rs.find(r => r.platform === p)); let ps = vals.map(r => r ? aPercentile(r, metric) : null); let pairs = ps.map((x, i) => ({ x, i })).filter(q => q.x !== null).sort((a, b) => b.x - a.x); let text = pairs.length < 2 ? 'Insufficient comparable samples' : pairs[0].x === pairs[1].x ? 'Similar relative positions' : `${A_PLATFORMS[pairs[0].i]} ranks highest within its own sample`; return `<tr><td><b>${esc(rs[0].title)}</b><br><span class="tiny muted">${esc(story)}</span></td>${vals.map((r, i) => `<td>${r && aNum(r[metric]) ? `<b>${aVal(r, metric)}</b><br>${ps[i] === null ? '<span class="tiny muted">Sample too small</span>' : `<span class="a-score">${aOrd(ps[i])} pct.</span>`}` : '<span class="muted">Not available</span>'}</td>`).join('')}<td class="small">${text}</td></tr>` }).join('')}</tbody></table></div>` : '<div class="empty-state">Matched story IDs are required to compare an idea across platforms. Import a shared story_id to activate the table.</div>' }
