function aTimingView() { let rs = aSelectedRows(), m = A_METRIC_MAP[aMetric]; if (!m.p.includes(aPlatform)) aMetric = 'views'; m = A_METRIC_MAP[aMetric]; let rows = aAvailable(aPlatform, aWindow, m.id); let byDay = {}; rows.forEach(r => { let d = aWeekday(r.published_at); (byDay[d] ??= []).push(r[m.id]) }); let daily = Object.entries(byDay).map(([day, v]) => ({ day, n: v.length, median: aMedian(v) })).sort((a, b) => b.median - a.median); let byHour = {}; rows.forEach(r => { let hr = (r.published_at || '').slice(11, 13); if (!hr) return; (byHour[hr] ??= []).push(r[m.id]) }); let hours = Object.entries(byHour).map(([hr, v]) => ({ hr, n: v.length, median: aMedian(v) })).sort((a, b) => b.median - a.median); let goodDays = daily.filter(x => x.n >= 3); let goodHours = hours.filter(x => x.n >= 3); return `${aFilters()}<div class="a-2col" style="margin-top:17px"><div class="a-panel"><div class="a-topline"><h3>Posting weekday</h3><span class="tag">Median ${esc(m.name.toLowerCase())}</span></div>${aTimingBars(daily, 'day')}<div class="a-note">${goodDays.length ? `Directional leading weekday with ≥3 posts: ${goodDays[0].day}.` : 'Insufficient matched posts per weekday to claim a best day. At least 3 comparable posts per group required.'}</div></div><div class="a-panel"><div class="a-topline"><h3>Posting hour</h3><span class="tag">Time as recorded in data</span></div>${aTimingBars(hours, 'hr')}<div class="a-note">${goodHours.length ? `Directional leading sampled hour: ${goodHours[0].hr}:00.` : 'Insufficient matched posts per hour to recommend a posting time.'} Imported timezone must be consistent.</div></div></div><div class="a-panel"><h3>Later scheduling integration</h3><p class="a-panel-desc">A genuine “best time” recommendation should combine your connected Later account’s audience-active-time signals with sufficient age-matched post outcomes. Later is not connected in this offline prototype, so its recommendations are not invented.</p><div class="row-spaced"><span class="tag warn">Later not connected</span><button class="btn outline small" onclick="toast('In production this would open an authorized Later integration setup.')">Integration plan ↗</button></div></div>` }
