  let rows = [], issues = [], dup = new Map(), dupCount = 0; for (let rowIdx = 1; rowIdx < parsed.length; rowIdx++) {
    let raw = Object.fromEntries(rawHead.map((h, j) => [h, (parsed[rowIdx][j] ?? '').trim()])); raw.platform = A_PLATFORMS.find(x => x.toLowerCase() === raw.platform.toLowerCase()) || raw.platform; raw.window = ({ '48 hours': '48h', '2d': '48h', '7 days': '7d', '1w': '7d', '30 days': '30d' })[raw.window.toLowerCase()] || raw.window.toLowerCase(); if (raw.post_id && !/^[^\s'"<>\\`]{1,200}$/.test(raw.post_id)) { issues.push(`Row ${rowIdx + 1}: post_id contains spaces, quotes or angle brackets`); continue } if (!A_PLATFORMS.includes(raw.platform)) { issues.push(`Row ${rowIdx + 1}: invalid platform (${raw.platform}); combined Meta refused`); continue } if (!A_WINDOWS.includes(raw.window)) { issues.push(`Row ${rowIdx + 1}: invalid age window (${raw.window})`); continue } if (!raw.post_id || !raw.snapshot_at || !raw.published_at || !raw.source || !raw.account) { issues.push(`Row ${rowIdx + 1}: required provenance is missing`); continue } let r = { ...raw }; for (let m of A_METRICS) { let cell = raw[m.id]; if (cell === '' || cell === undefined || cell === null) { r[m.id] = null; continue } let num = Number(cell.replace(/,/g, '')); if (!Number.isFinite(num)) { issues.push(`Row ${rowIdx + 1}: ${m.id} is not numeric`); r[m.id] = null; continue } if (!m.p.includes(raw.platform)) { issues.push(`Row ${rowIdx + 1}: ${m.id} is not native to ${raw.platform}; omitted`); r[m.id] = null; continue } r[m.id] = num }
    const k = [r.platform, r.account, r.post_id, r.window, r.snapshot_at].join('|'); if (dup.has(k)) { dupCount++; issues.push(`Row ${rowIdx + 1}: duplicate snapshot replaced earlier row`) } dup.set(k, r)
  } rows = [...dup.values()]; aDuplicateRemoved = dupCount;
