function caAttachPostFile(id, file) { if (!file.type.startsWith('image/') && !file.type.startsWith('video/')) { toast('Drop a photo or video on the post'); return } const p = state.posts.find(p => p.id === id); if (!p) return; const mediaId = Date.now() + Math.random(), m = { id: mediaId, name: file.name, type: file.type.startsWith('image/') ? 'image' : 'video', emoji: '▧', tag: 'Attached to post ' + p.id, sample: false }; state.media.unshift(m); mediaFiles[mediaId] = URL.createObjectURL(file); p.mediaId = mediaId; p.revision = (p.revision || 1) + 1; if (['approved', 'scheduled'].includes(p.status)) p.status = 'pending'; p.assets.unshift({ name: `Attached: ${file.name}`, status: 'found' }); save(); render(); toast('Visual attached. Missing requirements still need confirmation.'); caRememberThumb(mediaId, file) }
